def split_rag_chunks_4(text, source, size=40):
    chunks = []
    for index in range(0, len(text), size):
        part = text[index:index + size].strip()
        if part:
            chunks.append({'text': part, 'source': source, 'chunk_id': len(chunks) + 1})
    return chunks
